{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1724;--card:#0b1220;--accent:#f6c85f;--muted:#98a2b3;--glass:rgba(255,255,255,0.03)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#e6eef9;background:linear-gradient(180deg,#081022 0%,#071428 50%);}
    .pattern{background-image:url('assets/img/pattern.svg');background-repeat:repeat;}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);backdrop-filter: blur(6px)}
    nav a{color:#d6e7ff;margin:0 10px;text-decoration:none;font-weight:600;font-size:14px}
    .wrap{max-width:980px;margin:28px auto;padding:24px}
    .hero{display:grid;grid-template-columns:1fr 320px;gap:20px;align-items:start}
    .card{background:linear-gradient(180deg,var(--glass),transparent);padding:20px;border-radius:12px;box-shadow:0 6px 18px rgba(2,6,23,0.6)}
    h1{margin:0 0 8px 0;font-size:28px;color:#fff}
    p.lead{margin:0 0 12px 0;color:var(--muted);line-height:1.5}
    .who{font-size:14px;color:#cfe6ff}
    .mini-cta{display:inline-block;margin-top:12px;padding:10px 14px;background:var(--accent);color:#07202b;border-radius:9px;text-decoration:none;font-weight:700}
    .bio{margin-top:14px;color:#cbdff6}
    .side{font-size:14px;color:#dbeeff}
    .stat{background:#071428;padding:12px;border-radius:10px;margin-bottom:12px}
    .accordion{margin-top:18px}
    .acc-item{border-radius:9px;background:rgba(255,255,255,0.02);margin-bottom:10px;overflow:hidden}
    .acc-btn{width:100%;text-align:left;padding:14px;color:#e6f1ff;background:transparent;border:0;display:flex;justify-content:space-between;align-items:center;font-weight:700}
    .acc-body{padding:12px 14px;color:#bcd6f6;display:none;border-top:1px solid rgba(255,255,255,0.02)}
    .mood-line{display:flex;gap:8px;align-items:center;margin-top:16px}
    select{padding:8px;border-radius:8px;border:0;background:#071428;color:#dbeeff}
    .method{margin-top:14px;padding:14px;border-radius:10px;background:linear-gradient(180deg,#081026,transparent);color:#e9f5ff}
    footer{margin-top:18px;color:#9fb1cc;font-size:13px}
    a.primary{display:inline-block;margin-top:12px;padding:11px 16px;border-radius:10px;background:transparent;border:2px solid var(--accent);color:var(--accent);text-decoration:none;font-weight:700}
    .crisis{margin-top:12px;padding:12px;border-radius:9px;background:#2b1a1a;color:#ffeaea;font-size:13px}
    @media(max-width:840px){.hero{grid-template-columns:1fr;}.side{order:-1}}
  </style>
</head>
<body class="pattern">
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <strong style="color:var(--accent);letter-spacing:.6px">{{BUSINESS_NAME}}</strong>
      <small style="color:var(--muted)">Private practice • {{CITY}}, {{STATE}}</small>
    </div>
    <nav>
      <a href="index.html">Welcome</a>
      <a href="about.html">Story</a>
      <a href="specialties.html">Focus Areas</a>
      <a href="approach.html">How I Work</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Hello</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="hero card">
      <div>
        <h1>Hi — I'm a clinician who likes useful tools and quiet practice.</h1>
        <p class="lead">I offer short cohorts and individual sessions that aim to be practical, steady, and humane. I blend evidence-informed methods with everyday sense—so you leave with something you can actually use.</p>
        <div class="bio">
          <p class="who">I’m a licensed therapist with experience supporting adults through transitions, anxiety, relationship complexity, and grief. My work is pragmatic, kind, and rooted in collaboration. I care about clear agreements, confidentiality, and how therapy fits into your life.</p>
        </div>
        <a class="mini-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>

        <div class="accordion" aria-hidden="false">
          <div class="acc-item">
            <button class="acc-btn" data-acc="boundaries">Session boundaries<span>▸</span></button>
            <div class="acc-body" id="boundaries">Sessions are time-limited and scheduled in advance. We keep to start/end times and review cancellations, late arrivals, and rescheduling at intake. I’ll outline expected response times for messages and boundaries for contact between sessions.</div>
          </div>
          <div class="acc-item">
            <button class="acc-btn" data-acc="confidentiality">Confidentiality & limits<span>▸</span></button>
            <div class="acc-body" id="confidentiality">What we discuss is confidential except in legal or safety limits: imminent risk of harm to self or others, suspected abuse of a minor or vulnerable adult, or court orders. I’ll review limits and answer questions before we begin.</div>
          </div>
        </div>

        <div class="crisis" role="note">
          If you are in immediate danger or experiencing a life-threatening emergency, call local emergency services first. For urgent emotional crisis in the U.S., dial 988 or local crisis lines. If you’re outside the U.S., contact local emergency resources or crisis services.
        </div>

      </div>

      <aside class="side">
        <div class="stat card">
          <strong style="color:var(--accent)">A different kind of intake</strong>
          <p style="margin:8px 0 0;color:var(--muted)">Quick intake, clear expectations, and a short plan in the first three sessions—if that’s what you want.</p>
        </div>

        <div class="card">
          <label for="mood-select" style="font-weight:700">Tell me how today feels</label>
          <div class="mood-line">
            <select id="mood-select" aria-label="Choose current mood">
              <option value="neutral">Mostly okay, just checking in</option>
              <option value="anxious">Worry or nervous energy</option>
              <option value="stuck">Stuck or indecisive</option>
              <option value="heavy">Feeling heavy or low</option>
              <option value="angry">I’m irritated or angry</option>
            </select>
            <a id="primaryCta" class="primary" href="{{PRIMARY_CTA_URL}}" data-base="{{PRIMARY_CTA_LABEL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>

          <div class="method" id="mini-method">
            <strong>Suggested first step:</strong>
            <div id="mini-method-text">A brief consult to name what’s pressing and decide on a short plan—individual or cohort.</div>
          </div>
        </div>
      </aside>
    </section>

    <footer>
      <small>Interested in cohort options? I run small, time-limited groups focused on skills and mutual support—ask during your consult.</small>
    </footer>
  </main>

  <script>
    // Accordion
    document.querySelectorAll('.acc-btn').forEach(btn=>{
      btn.addEventListener('click',()=>{
        const key = btn.getAttribute('data-acc');
        const body = document.getElementById(key);
        const open = body.style.display === 'block';
        document.querySelectorAll('.acc-body').forEach(b=>b.style.display='none');
        document.querySelectorAll('.acc-btn span').forEach(s=>s.textContent='▸');
        if(!open){ body.style.display='block'; btn.querySelector('span').textContent='▾'; }
      });
    });

    // Mood-to-Method (mini)
    const miniMap = {
      neutral:{text:'A short intake to clarify priorities and co-create a plan — good for steady support.',cta:'Book a short consult'},
      anxious:{text:'Focus on grounding and practical tools to reduce immediate intensity and build tolerance.',cta:'Schedule a skills session'},
      stuck:{text:'Work on decision-focused steps and gentle behavior experiments to move forward.',cta:'Start a 3-session plan'},
      heavy:{text:'A paced check-in with grief- and mood-aware practices and a brief safety review.',cta:'Arrange a supportive consult'},
      angry:{text:'Explore what’s driving the anger and build actionable ways to respond rather than react.',cta:'Set up a focused session'}
    };
    const select = document.getElementById('mood-select');
    const miniText = document.getElementById('mini-method-text');
    const cta = document.getElementById('primaryCta');
    select.addEventListener('change',()=>{
      const val = select.value;
      const pick = miniMap[val]||miniMap.neutral;
      miniText.textContent = pick.text;
      cta.textContent = pick.cta + ' — ' + cta.getAttribute('data-base');
    });
  </script>
</body>
</html>"} 
