<body>
  <div class="wrap">
    <header>
      <div>
        <strong style="color:var(--accent)">{{BUSINESS_NAME}}</strong>
        <div style="color:var(--muted);font-size:13px">Private sessions & small cohorts • {{CITY}}, {{STATE}}</div>
      </div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="about.html">Story</a>
        <a href="specialties.html">Focus Areas</a>
        <a href="approach.html">How I Work</a>
        <a href="book.html">Reserve</a>
      </nav>
    </header>

    <main class="grid">
      <section>
        <h1>What I commonly work on</h1>
        <p style="color:var(--muted);margin-top:6px">Practical, evidence-informed support for life’s knottier spots. Pick a tile to read more or use the mood selector to get a quick recommendation.</p>

        <div class="card">
          <div class="spec">
            <h3>Transitions & Life Changes</h3>
            <p>Starting, stopping, or rearranging life. Short plans and cohort work to practice decision steps and manage uncertainty.</p>
          </div>
          <div class="spec">
            <h3>Anxiety & Worry</h3>
            <p>Skills-focused work to reduce reactivity and build tolerance: breathing, experiments, and cognitive framing.</p>
          </div>
          <div class="spec">
            <h3>Relationship Patterns</h3>
            <p>Communication practices, boundary-setting, and mapping patterns that repeat across relationships.</p>
          </div>
          <div class="spec">
            <h3>Grief & Loss</h3>
            <p>Respectful pacing, meaning-making, and safety checks—often in brief focused sequences.</p>
          </div>
        </div>

        <div class="accordion card">
          <h3 style="margin-top:0">Session boundaries & confidentiality</h3>
          <div class="acc-item">
            <button class="acc-btn" data-acc="sp-bound">Session boundaries ▸</button>
            <div class="acc-body" id="sp-bound">Sessions are typically 45–55 minutes. I’ll set expectations for cancellations, rescheduling, and contact. If you join a cohort, attendance norms will be reviewed in advance.</div>
          </div>
          <div class="acc-item">
            <button class="acc-btn" data-acc="sp-conf">Confidentiality & limits ▸</button>
            <div class="acc-body" id="sp-conf">Your notes are private. Exceptions include imminent risk of harm, mandated reporting, or court orders. We’ll discuss documentation and limits before we begin.</div>
          </div>

          <div class="crisis">If you are in immediate danger or a medical emergency, call local emergency services. For urgent emotional crisis in the U.S., call 988 or your local crisis number. I cannot provide crisis management via email.</div>
        </div>

      </section>

      <aside>
        <div class="card">
          <label for="mood">How are you today?</label>
          <div class="moodbox">
            <select id="mood" aria-label="Choose current mood">
              <option value="anxious">Anxious or restless</option>
              <option value="stuck">Stuck / indecisive</option>
              <option value="sad">Low / grieving</option>
              <option value="relationship">Relationship stress</option>
              <option value="curious">Curious about cohort or skills</option>
            </select>
          </div>

          <div class="recommend" id="recommend">
            <strong>Recommended focus</strong>
            <p id="recommend-text" style="margin:8px 0;color:var(--muted)">Choose a mood to see a tailored suggestion and the best next step.</p>
            <a id="spec-cta" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>

        <div class="card" style="margin-top:12px">
          <strong style="color:var(--accent)">Cohort offering</strong>
          <p style="color:var(--muted);margin-top:8px">Small groups meet for 6 weeks with skill practice and check-ins. Not for crisis care; cohorts have clear attendance and confidentiality guidelines.</p>
        </div>
      </aside>
    </main>
  </div>

  <script>
    // Accordion
    document.querySelectorAll('.acc-btn').forEach(b=>b.addEventListener('click',()=>{
      const id = b.getAttribute('data-acc');
      const el = document.getElementById(id.replace('sp-','')) || document.getElementById(id);
      // map to element ids
      const map = { 'sp-bound':'sp-bound','sp-conf':'sp-conf' };
      const target = document.getElementById(id.replace('sp-','')) || document.getElementById(id);
      const body = document.getElementById(id.replace('sp-',''));
      // simpler toggle using nextElement
      const next = b.nextElementSibling;
      const open = next.style.display === 'block';
      document.querySelectorAll('.acc-body').forEach(x=>x.style.display='none');
      document.querySelectorAll('.acc-btn').forEach(x=>x.textContent = x.textContent.replace('▾','▸'));
      if(!open){ next.style.display='block'; b.textContent = b.textContent.replace('▸','▾'); }
    }));

    // Mood-to-method mapping
    const map = {
      anxious:{text:'Short-term sessions emphasizing grounding skills, pacing, and experiments to reduce worry. Good fit: a 4-session skills plan or weekly support.',cta:'Request a skills consult'},
      stuck:{text:'Decision-focused work and small action steps to test possibilities—often a 3-session focused series.',cta:'Start a 3-session plan'},
      sad:{text:'Paced support with attention to safety, loss, and reconnection strategies. Consider individual sessions with brief check-ins.',cta:'Book a supportive consult'},
      relationship:{text:'Communications mapping and boundary practice; sometimes short couples work or individual pattern mapping.',cta:'Schedule a relationship session'},
      curious:{text:'Join a time-limited cohort to practice together and learn concrete tools in a supportive group.',cta:'Learn about cohorts'}
    };

    const sel = document.getElementById('mood');
    const textEl = document.getElementById('recommend-text');
    const cta = document.getElementById('spec-cta');
    sel.addEventListener('change',()=>{
      const v = sel.value;
      const pick = map[v]||map.curious;
      textEl.textContent = pick.text;
      cta.textContent = pick.cta + ' — ' + cta.textContent;
    });
  </script>
</body>
